package com.androidhit.lumadrift.qa;

import android.app.*;
import android.accessibilityservice.AccessibilityServiceInfo;
import android.content.*;
import android.content.pm.PackageInfo;
import android.graphics.*;
import android.os.*;
import android.view.accessibility.AccessibilityNodeInfo;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.Predicate;

/** SDK framework-only tests. All app mutations use real accessible controls. */
public final class CandidateUiInstrumentation extends Instrumentation {
    private static final String TARGET="com.androidhit.lumadrift.sandbox";
    private Bundle args;private UiAutomation ui;private File output;private final JSONArray checks=new JSONArray();private final JSONArray captures=new JSONArray();private int count;private Activity activity;
    @Override public void onCreate(Bundle arguments){super.onCreate(arguments);args=arguments==null?new Bundle():arguments;start();}
    @Override public void onStart(){new Thread(()->{Bundle result=new Bundle();boolean passed=false;try{
        if(!TARGET.equals(getTargetContext().getPackageName()))throw new AssertionError("Lab target only");
        ui=getUiAutomation();AccessibilityServiceInfo info=ui.getServiceInfo();info.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS|AccessibilityServiceInfo.FLAG_INCLUDE_NOT_IMPORTANT_VIEWS;ui.setServiceInfo(info);
        output=new File(getTargetContext().getExternalFilesDir(null),"v17-sdk-ui");if(!output.exists()&&!output.mkdirs())throw new IOException("Cannot create output");
        PackageInfo version=getTargetContext().getPackageManager().getPackageInfo(TARGET,0);check(version.versionCode==8&&version.versionName.startsWith("1.7."),"Installed Lab candidate 1.7/code8");
        launch();english();capture("home-en");String cases=args.getString("cases","menus,map,social,capsule,challenge,journey,landscape,languages");
        if(cases.contains("menus"))menus();if(cases.contains("map"))map();if(cases.contains("social"))social();if(cases.contains("capsule"))capsule();if(cases.contains("challenge"))challenge();if(cases.contains("journey"))journey();if(cases.contains("landscape"))landscape();if(cases.contains("languages"))french();
        passed=true;result.putString("summary","PASS "+count+" checks; "+captures.length()+" original SDK screenshots");
    }catch(Throwable failure){result.putString("failure",failure.toString());try{if(output!=null){capture("failure");write("failure.txt",stack(failure));}}catch(Throwable ignored){}}
    finally{try{JSONObject report=new JSONObject().put("passed",passed).put("checks",checks).put("captures",captures).put("checkCount",count).put("package",TARGET).put("sdk",Build.VERSION.SDK_INT).put("abi",Build.SUPPORTED_ABIS[0]).put("scope","Actual SDK AccessibilityNodeProvider/UiAutomation actions; no preference injection, account, ad or payment");if(output!=null)write("report.json",report.toString(2));}catch(Throwable ignored){}finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}},"luma-sdk-ui-tests").start();}
    private void launch()throws Exception{Intent intent=new Intent().setClassName(TARGET,"com.androidhit.lumadrift.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);activity=startActivitySync(intent);SystemClock.sleep(550);waitFor(x->x.startsWith("Luma Drift · "),false,5000);}
    private void english()throws Exception{click(x->Arrays.asList("Settings","Paramètres","Einstellungen","Ajustes","Definições","Impostazioni").contains(x),false);clickExact("English",true);back();waitFor(x->x.equals("Home"),true,4000);}
    private List<AccessibilityNodeInfo> nodes(){if(Build.VERSION.SDK_INT>=33)ui.clearCache();List<AccessibilityNodeInfo> out=new ArrayList<>();AccessibilityNodeInfo root=ui.getRootInActiveWindow();if(root==null)return out;ArrayDeque<AccessibilityNodeInfo> queue=new ArrayDeque<>();queue.add(root);while(!queue.isEmpty()&&out.size()<500){AccessibilityNodeInfo node=queue.remove();out.add(node);for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo child=node.getChild(i);if(child!=null)queue.add(child);}}return out;}
    private static String name(AccessibilityNodeInfo n){CharSequence value=n.getContentDescription();if(value==null||value.length()==0)value=n.getText();return value==null?"":value.toString();}
    private AccessibilityNodeInfo find(Predicate<String> predicate,boolean clickable){List<AccessibilityNodeInfo> all=nodes();AccessibilityNodeInfo found=null;for(AccessibilityNodeInfo n:all){Rect r=new Rect();n.getBoundsInScreen(r);if(found==null&&(!clickable||n.isClickable())&&n.isEnabled()&&n.isVisibleToUser()&&r.width()>0&&r.height()>0&&predicate.test(name(n)))found=AccessibilityNodeInfo.obtain(n);}for(AccessibilityNodeInfo n:all)n.recycle();return found;}
    private AccessibilityNodeInfo waitFor(Predicate<String> predicate,boolean clickable,long timeout)throws Exception{long end=SystemClock.uptimeMillis()+timeout;do{AccessibilityNodeInfo n=find(predicate,clickable);if(n!=null)return n;SystemClock.sleep(80);}while(SystemClock.uptimeMillis()<end);throw new AssertionError("Missing control; visible="+labels());}
    private List<String> labels(){List<String> out=new ArrayList<>();for(AccessibilityNodeInfo n:nodes()){out.add(name(n));n.recycle();}return out;}
    private void clickExact(String label,boolean seek)throws Exception{click(x->x.equalsIgnoreCase(label),seek);}
    private void click(Predicate<String> predicate,boolean seek)throws Exception{for(int i=0;i<(seek?12:1);i++){AccessibilityNodeInfo n=find(predicate,true);if(n!=null){String label=name(n);if(label.startsWith("Sign in with Google")||label.contains("Simulate")||label.contains("Watch ad")||label.startsWith("LumaGold"))throw new AssertionError("Forbidden provider/payment control: "+label);boolean ok=n.performAction(AccessibilityNodeInfo.ACTION_CLICK);n.recycle();if(!ok)throw new AssertionError("SDK rejected click: "+label);SystemClock.sleep(160);return;}if(seek)scroll(true);}throw new AssertionError("Missing clickable control; visible="+labels());}
    private boolean scroll(boolean forward){AccessibilityNodeInfo host=find(x->x.startsWith("Luma Drift · "),false);if(host==null)return false;boolean success=host.performAction(forward?AccessibilityNodeInfo.ACTION_SCROLL_FORWARD:AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD);host.recycle();SystemClock.sleep(130);return success;}
    private void top(){for(int i=0;i<9;i++)if(!scroll(false))break;}
    private void back(){ui.performGlobalAction(1);SystemClock.sleep(180);}
    private void home()throws Exception{AccessibilityNodeInfo button=find(x->x.equals("Home"),true);if(button!=null){button.performAction(AccessibilityNodeInfo.ACTION_CLICK);button.recycle();SystemClock.sleep(180);return;}launch();}
    private int coins(){return getTargetContext().getSharedPreferences("luma_drift_save_v1",0).getInt("coins",0);}
    private int stock(){return getTargetContext().getSharedPreferences("luma_drift_save_v1",0).getInt("booster_hint",0);}
    private SharedPreferences session(){return getTargetContext().getSharedPreferences("luma_session",0);}
    private void menus()throws Exception{
        click(x->x.startsWith("Daily rewards"),true);top();capture("rewards-before-en");int before=coins();String claim=null;for(String label:labels())if((label.startsWith("Claim +")||label.startsWith("Collect +"))&&label.endsWith(" LumaCoins")){claim=label;break;}
        if(claim!=null){int amount=Integer.parseInt(claim.replaceAll("^.*\\+(\\d+) LumaCoins$","$1"));clickExact(claim,false);check(coins()==before+amount,"Daily gift adds exactly the advertised earned coins once");}else check(labels().contains("Collected today"),"Existing daily receipt is explicitly already collected");
        int claimed=coins();clickExact("Collected today",false);check(coins()==claimed,"Daily reward repeated action cannot add coins twice");capture("rewards-claimed-en");click(x->x.equals("Weekly quests")||x.equals("Weekly Voyage"),false);capture("weekly-quests-en");home();
        click(x->x.startsWith("Dressing room,"),true);top();capture("wardrobe-hat-en");int startCoins=coins();String[] slots={"Hat","Outfit","Shoes","Gloves"};
        for(String slot:slots){top();clickExact(slot,false);String first=null;for(String label:labels())if(label.startsWith(slot+" · Dew,")){first=label;break;}check(first!=null&&first.contains("Equipped"),"Starter "+slot+" has explicit equipped ownership state");clickExact(first,true);waitFor(x->x.equals(slot+" · Dew"),false,2000);capture("wardrobe-"+slot.toLowerCase(Locale.ROOT)+"-preview-en");clickExact("Equip",false);check(coins()==startCoins,"Equipping owned "+slot+" costs no coins");capture("wardrobe-"+slot.toLowerCase(Locale.ROOT)+"-en");String locked=null;for(String label:labels())if(label.startsWith(slot+" · ")&&label.contains(", To unlock,")){locked=label;break;}if(locked!=null){String title=locked.substring(0,locked.indexOf(','));clickExact(locked,true);waitFor(x->x.equals(title),false,2000);capture("wardrobe-"+slot.toLowerCase(Locale.ROOT)+"-locked-preview-en");clickExact("Cancel",false);check(coins()==startCoins,"Cancelling an unowned "+slot+" preview spends no coins");}}
        home();clickExact("Shop",true);top();capture("shop-earned-en");check(labels().stream().anyMatch(x->x.startsWith("LumaCoins:")),"Shop exposes the earned LumaCoins balance");boolean premium=false;for(int i=0;i<12;i++){AccessibilityNodeInfo node=find(x->x.startsWith("LumaGold,"),true);if(node!=null){premium=name(node).contains("Real checkout is not open");node.recycle();break;}scroll(true);}check(premium,"Shop distinguishes the closed premium LumaGold account currency");capture("shop-premium-closed-en");int vaultCoins=coins();AccessibilityNodeInfo vault=waitFor(x->x.startsWith("LumaGold,"),true,2000);check(vault.performAction(AccessibilityNodeInfo.ACTION_CLICK),"Closed premium catalogue opens as a preview route only");vault.recycle();waitFor(x->x.equals("The star wardrobe"),false,4000);check(labels().stream().anyMatch(x->x.contains("Paid draws are closed")),"Premium account wardrobe honestly declares paid draws closed");boolean disabled=false;for(AccessibilityNodeInfo item:nodes()){if(name(item).equals("Paid draws are closed")&&String.valueOf(item.getClassName()).endsWith("Button"))disabled=!item.isEnabled();item.recycle();}check(disabled&&labels().contains("My Google account"),"Guest vault has a disabled draw control and optional account access, without opening the chooser");check(coins()==vaultCoins,"Viewing the closed vault cannot spend earned coins");capture("vault-guest-closed-en");back();home();
    }
    private void social()throws Exception{home();click(x->x.startsWith("Friends & gifts,"),true);waitFor(x->x.equals("Stars find each other"),false,3000);check(labels().stream().anyMatch(x->x.contains("Your adventure stays playable without an account")),"Social guest screen explains optional Google login without inventing friends");capture("social-guest-en");back();}
    private void capsule()throws Exception{home();clickExact("Shop",true);int before=coins();if(before<150){check(true,"Capsule spend skipped because this real local profile has fewer than150 earned coins");return;}click(x->x.startsWith("Star capsule,"),true);check(labels().stream().anyMatch(x->x.contains("common 7.5%")&&x.contains("rare 3.75%")&&x.contains("epic 1.25%")),"Native capsule confirmation discloses every item probability before a spend");capture("capsule-odds-en");clickExact("Open · 150 LumaCoins",false);int refund=0;for(String label:labels())if(label.matches("(?s).*\\+\\d+ LumaCoins.*")){java.util.regex.Matcher match=java.util.regex.Pattern.compile("\\+(\\d+) LumaCoins").matcher(label);if(match.find())refund=Integer.parseInt(match.group(1));}check(coins()==before-150+refund,"An earned capsule debits exactly150 coins with only the disclosed duplicate compensation");check(refund==0||refund==25||refund==60||refund==100,"Capsule grants a new cosmetic or the explicit rarity-based earned duplicate refund");capture("capsule-reveal-en");int after=coins();clickExact("Equip",false);check(coins()==after,"Equipping the earned capsule result adds no second spend");home();}
    private void map()throws Exception{home();clickExact("Map",true);for(int n:new int[]{1,13,100,101,1000}){clickExact("Explore a level",false);setInput(Integer.toString(n));clickExact("Continue",false);check(labels().stream().anyMatch(x->x.startsWith("Level "+n+",")),"Map jump exposes level "+n+" with a real accessibility label");capture("map-"+n+"-en");}boolean moved=scroll(false);check(moved,"Saga map supports native accessibility scroll backward");capture("map-scroll-en");home();}
    private void setInput(String text)throws Exception{List<AccessibilityNodeInfo> all=nodes();AccessibilityNodeInfo edit=null;for(AccessibilityNodeInfo n:all)if(n.isEditable()&&edit==null)edit=AccessibilityNodeInfo.obtain(n);for(AccessibilityNodeInfo n:all)n.recycle();if(edit==null)throw new AssertionError("Native dialog text input absent");Bundle action=new Bundle();action.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,text);check(edit.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,action),"Native dialog accepts text through SDK accessibility");edit.recycle();SystemClock.sleep(100);}
    private JSONObject fixture(int number)throws Exception{try(InputStream in=getContext().getAssets().open("fixtures/j"+number+".json")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)bytes.write(buffer,0,n);return new JSONObject(bytes.toString("UTF-8"));}}
    private void piece(JSONObject step)throws Exception{int row=step.getInt("row")+1,col=step.getInt("col")+1;click(x->x.contains("Piece, row "+row+", column "+col+", arrow "),false);}
    private void challenge()throws Exception{home();int before=coins(),hints=stock();clickExact("Enter a challenge",true);setInput(fixture(13).getString("code"));clickExact("Play",false);check(session().getInt("mode",-1)==4,"Public J13 challenge import opens fair challenge mode");capture("j13-challenge-en");check(labels().stream().noneMatch(x->x.startsWith("Spark:")),"Imported challenge does not offer paid or stock power buttons");JSONArray steps=fixture(13).getJSONArray("steps");for(int i=0;i<steps.length();i++)piece(steps.getJSONObject(i));waitFor(x->x.startsWith("Lovely drift!"),false,4000);check(coins()==before&&stock()==hints,"Finishing imported J13 challenge grants no earned coins and spends no stock");capture("j13-challenge-cleared-en");home();}
    private void journey()throws Exception{
        home();clickExact("Map",true);clickExact("Explore a level",false);setInput("1");clickExact("Continue",false);click(x->x.startsWith("Level 1,"),false);click(x->x.equals("Play")||x.startsWith("Play "),true);
        for(int n=1;n<=12;n++){JSONArray steps=fixture(n).getJSONArray("steps");for(int i=0;i<steps.length();i++)piece(steps.getJSONObject(i));waitFor(x->x.startsWith("Lovely drift!"),false,4000);check(getTargetContext().getSharedPreferences("luma_drift_save_v1",0).getInt("stars_"+n,0)>0,"Journey "+n+" is cleared by actual piece actions, with no profile seeding");click(x->x.startsWith("Next"),false);click(x->x.equals("Play")||x.startsWith("Play "),true);}
        check(session().getInt("level",-1)==13,"Real first-twelve clears unlock normal Journey13");JSONArray steps=fixture(13).getJSONArray("steps");int guardStock=stock();piece(steps.getJSONObject(0));click(x->x.contains("Undo"),true);piece(steps.getJSONObject(0));click(x->x.contains("Undo"),true);check(session().getInt("budget_used",-1)==4&&session().getString("history","bad").isEmpty(),"J13 move/undo/move/undo spends4 actions and restores all10 pieces");click(x->x.startsWith("Spark:"),true);check(stock()==guardStock&&find(x->x.equalsIgnoreCase("Use one charge"),true)==null,"An insufficient-budget J13 hint cannot open a consuming confirmation or spend stock");capture("j13-needs-actions-guard-en");click(x->x.contains("Restart"),true);clickExact("Restart",false);check(session().getInt("budget_used",-1)==0,"Free restart restores J13 allowance after the insufficient-budget guard");for(int i=0;i<4;i++)piece(steps.getJSONObject(i));int before=stock(),used=session().getInt("budget_used",-99);click(x->x.startsWith("Spark:"),true);clickExact("Use one charge",false);check(stock()==before-1,"Spark consumes exactly one earned hint charge");check(session().getInt("hint_id",-1)==4,"Journey13 hint chooses the exact completion-preserving next tile4");check(session().getInt("budget_used",-99)==used,"Hint itself consumes no move");capture("j13-safe-hint-en");click(x->x.startsWith("Spark:"),true);check(stock()==before-1,"Tapping an active hint cannot consume another charge");
        JSONObject trap=null;JSONArray tiles=fixture(13).getJSONArray("tiles");for(int i=0;i<tiles.length();i++)if(tiles.getJSONObject(i).getInt("id")==8)trap=tiles.getJSONObject(i);piece(trap);waitFor(x->x.equals("This path is closed"),true,3000);capture("j13-dead-end-banner-en");clickExact("This path is closed",false);check(labels().stream().anyMatch(x->x.contains("Extra moves alone cannot repair it")),"Dead-end guidance explains that extra paid moves do not repair gates");capture("j13-dead-end-dialog-en");clickExact("Close",false);click(x->x.contains("Undo"),true);check(session().getInt("undos",0)>0,"Native Undo restores the solvable J13 prefix");
        click(x->x.contains("Restart"),true);clickExact("Restart",false);for(int i=0;i<steps.length();i++)piece(steps.getJSONObject(i));waitFor(x->x.startsWith("Lovely drift!"),false,4000);check(getTargetContext().getSharedPreferences("luma_drift_save_v1",0).getInt("stars_13",0)>0,"Normal Journey13 clears within its move allowance through actual UI actions");capture("j13-journey-cleared-en");home();
    }
    private void landscape()throws Exception{home();clickExact("Map",true);android.view.WindowManager manager=(android.view.WindowManager)getTargetContext().getSystemService(Context.WINDOW_SERVICE);int original=manager.getDefaultDisplay().getRotation();boolean locked=android.provider.Settings.System.getInt(getTargetContext().getContentResolver(),android.provider.Settings.System.ACCELEROMETER_ROTATION,0)==0;try{check(ui.setRotation(UiAutomation.ROTATION_FREEZE_90),"SDK rotates the QA app to compact landscape");SystemClock.sleep(800);clickExact("Explore a level",false);setInput("101");clickExact("Continue",false);AccessibilityNodeInfo jump=waitFor(x->x.equals("Explore a level"),true,3000),level=waitFor(x->x.startsWith("Level 101,"),true,3000);Rect header=new Rect(),node=new Rect();jump.getBoundsInScreen(header);level.getBoundsInScreen(node);jump.recycle();level.recycle();check(!Rect.intersects(header,node)&&node.top>=header.bottom,"Landscape saga node101 remains below the pinned compact header");check(header.height()/getTargetContext().getResources().getDisplayMetrics().density>=48f,"Landscape jump control preserves at least48dp physical touch height");capture("map-landscape-101-en");}finally{ui.setRotation(locked?original:UiAutomation.ROTATION_UNFREEZE);SystemClock.sleep(700);}check(manager.getDefaultDisplay().getRotation()==original,"SDK restores the original display rotation after landscape");home();}
    private void french()throws Exception{home();clickExact("Settings",false);clickExact("Français",true);back();capture("home-fr");click(x->x.startsWith("Récompenses du jour"),true);capture("rewards-fr");clickExact("Accueil",true);click(x->x.startsWith("Dressing,"),true);capture("wardrobe-fr");clickExact("Accueil",true);clickExact("Carte",true);clickExact("Explorer un niveau",false);setInput("1000");clickExact("Continuer",false);capture("map-1000-fr");}
    private void check(boolean condition,String message)throws Exception{count++;checks.put(new JSONObject().put("pass",condition).put("message",message));if(!condition)throw new AssertionError(message);Bundle status=new Bundle();status.putString("stream","PASS "+message+"\\n");sendStatus(0,status);}
    private void capture(String name)throws Exception{SystemClock.sleep(100);Bitmap pixels=ui.takeScreenshot();if(pixels==null)throw new IOException("SDK screenshot unavailable");try(OutputStream file=new FileOutputStream(new File(output,name+".png"))){if(!pixels.compress(Bitmap.CompressFormat.PNG,100,file))throw new IOException("PNG encoding failed");}finally{pixels.recycle();}JSONArray nodes=new JSONArray();for(AccessibilityNodeInfo node:nodes()){Rect bounds=new Rect();node.getBoundsInScreen(bounds);nodes.put(new JSONObject().put("name",name(node)).put("clickable",node.isClickable()).put("class",String.valueOf(node.getClassName())).put("bounds",bounds.toShortString()));node.recycle();}write(name+".json",nodes.toString(2));captures.put(name);}
    private void write(String name,String text)throws IOException{try(OutputStream out=new FileOutputStream(new File(output,name))){out.write(text.getBytes(StandardCharsets.UTF_8));}}
    private static String stack(Throwable failure){StringWriter text=new StringWriter();failure.printStackTrace(new PrintWriter(text));return text.toString();}
}
